    private static string language = Resolve("auto");
    internal static string CurrentCode => language;

    internal static void Configure(string code) => language = Resolve(code);

    internal static string T(string key)
    {
        if (ExtraText.TryGetValue(language, out var extra) && extra.TryGetValue(key, out var translated))
            return translated;
        if (!Text.TryGetValue(key, out var values)) return key;
        var index = Array.IndexOf(ValueLanguages, language);
        if (index < 0 || index >= values.Length) index = 2;
        return values[index];
    }

    internal static string F(string key, params object[] values) =>
        string.Format(CultureInfo.CurrentCulture, T(key), values);

    private static string Resolve(string code)
    {
        code = code switch { "ja" => "ja-JP", "ko" => "ko-KR", "de" => "de-DE", "fr" => "fr-FR", "th" => "th-TH", "vi" => "vi-VN", _ => code };
        code = code switch { "ja-JP" => "ja", "ko-KR" => "ko", "de-DE" => "de", "fr-FR" => "fr", "th-TH" => "th", "vi-VN" => "vi", _ => code };
        if (code is "ru-RU" or "pt-BR" or "es-ES") return code;
        if (!string.IsNullOrWhiteSpace(code) && !code.Equals("auto", StringComparison.OrdinalIgnoreCase) &&
            Array.IndexOf(ValueLanguages, code) >= 0) return code;
        var culture = CultureInfo.CurrentUICulture.Name;
        if (culture.StartsWith("zh", StringComparison.OrdinalIgnoreCase))
            return culture.Contains("TW", StringComparison.OrdinalIgnoreCase) ||
                   culture.Contains("HK", StringComparison.OrdinalIgnoreCase) ||
                   culture.Contains("Hant", StringComparison.OrdinalIgnoreCase) ? "zh-TW" : "zh-CN";
        if (culture.StartsWith("ru", StringComparison.OrdinalIgnoreCase)) return "ru-RU";
        if (culture.StartsWith("pt", StringComparison.OrdinalIgnoreCase)) return "pt-BR";
        if (culture.StartsWith("es", StringComparison.OrdinalIgnoreCase)) return "es-ES";
        foreach (var candidate in new[] { "ja", "ko", "de", "fr", "th", "vi" })
            if (culture.StartsWith(candidate, StringComparison.OrdinalIgnoreCase)) return candidate;
        return "en";
    }
}
